Here's a concise React authentication component with TypeScript:

```typescript
interface AuthState {
  isAuthenticated: boolean;
  token: string | null;
  user: any;
}

interface LoginCredentials {
  email: string;
  password: string;
}

const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [auth, setAuth] = useState<AuthState>({
    isAuthenticated: false,
    token: localStorage.getItem('token'),
    user: null
  });

  const login = async (credentials: LoginCredentials) => {
    try {
      const response = await fetch('/api/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(credentials)
      });

      const data = await response.json();

      if (data.token) {
        localStorage.setItem('token', data.token);
        setAuth({
          isAuthenticated: true,
          token: data.token,
          user: data.user
        });
        return true;
      }
    } catch (error) {
      console.error('Login failed:', error);
      return false;
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    setAuth({
      isAuthenticated: false,
      token: null,
      user: null
    });
  };

  // Axios interceptor for automatic token inclusion
  useEffect(() => {
    if (auth.token) {
      axios.interceptors.request.use(config => {
        config.headers.Authorization = `Bearer ${auth.token}`;
        return config;
      });
    }
  }, [auth.token]);

  return (
    <AuthContext.Provider value={{ ...auth, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

// Usage example:
const LoginForm = () => {
  const { login } = useContext(AuthContext);
  const [credentials, setCredentials] = useState<LoginCredentials>({
    email: '',
    password: ''
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await login(credentials);
  };

  return (
    <form onSubmit={handleSubmit}>
      <input 
        type="email"
        value={credentials.email}
        onChange={e => setCredentials({...credentials, email: e.target.value})}
      />
      <input 
        type="password"
        value={credentials.password}
        onChange={e => setCredentials({...credentials, password: e.target.value})}
      />
      <button type="submit">Login</button>
    </form>
  );
};
```

Key features:
- TypeScript interfaces for type safety
- JWT token storage in localStorage
- Context API for global auth state
- Axios interceptor for auth headers
- Login/logout functionality
- Protected route wrapper available

To use:
1. Wrap your app with `AuthProvider`
2. Access auth context with `useContext(AuthContext)`
3. Use `login()` and `logout()` methods
4. Token automatically included in requests

